          { isEquivalence = record
              { refl = IsEquivalence.refl e₁ , IsEquivalence.refl e₂
              ; sym = λ { (p , q) → IsEquivalence.sym e₁ p , IsEquivalence.sym e₂ q }
              ; trans = λ { (p , q) (r , s) → IsEquivalence.trans e₁ p r , IsEquivalence.trans e₂ q s }
              }
          ; reflexive = λ { (p , q) → inj₂ (p , IsPreorder.reflexive p₂ q) }
          ; trans = λ { (inj₂ (p , q)) (inj₂ (r , s)) → inj₂ (IsEquivalence.trans e₁ p r , IsPreorder.trans p₂ q s) }
          }
      ; antisym = λ { (p , q) (r , s) → IsPartialOrder.antisym o₁ p r , IsPartialOrder.antisym o₂ q s }
      }
  ; total = λ { (a , b) (c , d) → inj₁ (inj₂ (IsTotalOrder.total ord₁ a c , IsTotalOrder.total ord₂ b d)) }
  }
